 static HttpRequest rq(String url,String method,String body,List<HttpHeader> hs){HttpRequest fallback=requestAdapter(url,method,body,hs);return proxy(HttpRequest.class,(p,m,args)->switch(m.getName()){
  case "withMethod"->rq(url,args[0].toString(),body,hs);case "withBody"->rq(url,method,args[0] instanceof burp.api.montoya.core.ByteArray b?new String(b.getBytes(),StandardCharsets.UTF_8):args[0].toString(),hs);
  case "withHeader"->{List<HttpHeader> n=new ArrayList<>(hs);String name=args[0] instanceof HttpHeader h?h.name():args[0].toString(),value=args[0] instanceof HttpHeader h?h.value():args[1].toString();n.removeIf(h->h.name().equalsIgnoreCase(name));n.add(header(name,value));yield rq(url,method,body,n);}
  case "withRemovedHeader"->{List<HttpHeader> n=new ArrayList<>(hs);String name=args[0] instanceof HttpHeader h?h.name():args[0].toString();n.removeIf(h->h.name().equalsIgnoreCase(name));yield rq(url,method,body,n);}
  case "parameters"->parameters(url,body,hs);default->m.invoke(fallback,args);
 });}
 static List<ParsedHttpParameter> parameters(String url,String body,List<HttpHeader> hs){List<ParsedHttpParameter> out=new ArrayList<>();String query=URI.create(url).getRawQuery();if(query!=null)param(out,query,HttpParameterType.URL);if(hs.stream().anyMatch(h->h.name().equalsIgnoreCase("Content-Type")&&h.value().contains("x-www-form-urlencoded")))param(out,body,HttpParameterType.BODY);return out;}
 static void param(List<ParsedHttpParameter> out,String text,HttpParameterType type){for(String pair:text.split("&")){String[] parts=pair.split("=",2);String name=URLDecoder.decode(parts[0],StandardCharsets.UTF_8),value=URLDecoder.decode(parts.length<2?"":parts[1],StandardCharsets.UTF_8);out.add(proxy(ParsedHttpParameter.class,(p,m,args)->switch(m.getName()){case "name"->name;case "value"->value;case "type"->type;default->def(m);}));}}
 static HttpRequest real(String path,String method,Account a,String body,String type){List<HttpHeader> hs=new ArrayList<>();if(!a.cookie().isEmpty())hs.add(header("Cookie",a.cookie()));if(!a.csrf().isEmpty())hs.add(header("X-CSRF-Token",a.csrf()));if(!type.isEmpty())hs.add(header("Content-Type",type));return rq(base+path,method,body,hs);}
